// WI-14 (docs/plans/M8.md, H-8, ASM-976): the extended dashboard layout, in a real browser. A NEW spec file:
// dashboard.spec.ts (M5b) stays byte-identical; its two screenshot baselines (dashboard-{ops,day}.png at
// 1280x800, left panel collapsed) are regenerated by the implementer and reviewed by the human. Baselines for
// this file do not exist yet: the implementer generates them with `bun run test:e2e --update-snapshots
// dashboard-layout.spec.ts`; the screenshot tests fail until then.
//
// No engine runs in the `ui` project, so the stream fails and the page sits in `reconnecting`: the panels show
// their empty states. The map canvas is hidden for the screenshot, as in dashboard.spec.ts (a Playwright `mask`
// paints over the element's whole box and the map is full-bleed, so it would hide the bar and the panels too).
import AxeBuilder from "@axe-core/playwright";
import { expect, type Page, test } from "@playwright/test";

type Theme = "ops" | "day";
const THEMES: Theme[] = ["ops", "day"];
const NARROW = { width: 1280, height: 800 };
const WIDE = { width: 1600, height: 900 };
const SHOT = {
  maxDiffPixelRatio: 0.001,
  threshold: 0.05,
  animations: "disabled",
  caret: "hide",
} as const;

async function openDashboard(
  page: Page,
  theme: Theme,
  viewport: { width: number; height: number },
): Promise<void> {
  await page.setViewportSize(viewport);
  await page.goto("/");
  await expect(page.getByRole("alert", { name: "Engine not reachable" })).toBeVisible();
  await expect(page.getByRole("region", { name: "Live map" })).toBeVisible();
  if (theme === "day") await page.getByRole("switch", { name: "Day theme" }).click();
  await expect(page.locator("html")).toHaveAttribute(
    "data-theme",
    theme === "day" ? "light" : "dark",
  );
  await page.mouse.move(0, 0);
  await page.evaluate(async () => {
    await document.fonts.ready;
  });
  await page.evaluate(() => new Promise<void>((done) => requestAnimationFrame(() => done())));
}

const entitiesPanel = (page: Page) => page.getByRole("complementary", { name: "Entities" });
const panelToggle = (page: Page) =>
  entitiesPanel(page).getByRole("button", { name: /^(Collapse|Expand) panel$/ });

for (const theme of THEMES) {
  test(`dashboard with the left panel open (${theme})`, async ({ page }) => {
    await openDashboard(page, theme, WIDE);
    await expect(panelToggle(page)).toHaveAttribute("aria-expanded", "true");
    await expect(page.locator(".maplibregl-canvas")).toHaveCount(1); // the hiding rule must hit something
    await page.addStyleTag({ content: ".maplibregl-canvas { visibility: hidden !important; }" });
    await expect(page).toHaveScreenshot(`dashboard-wide-${theme}.png`, SHOT);
  });

  test(`dashboard with the log tab open has no accessibility violations (${theme})`, async ({
    page,
  }) => {
    await openDashboard(page, theme, WIDE);
    await entitiesPanel(page).getByRole("tab", { name: "Log" }).click();
    const results = await new AxeBuilder({ page }).exclude(".maplibregl-canvas").analyze();
    expect(
      results.violations.map((v) => `${v.id}: ${v.nodes.map((n) => n.target).join(", ")}`),
    ).toEqual([]);
  });

  test(`dashboard with the entities tab open has no accessibility violations (${theme})`, async ({
    page,
  }) => {
    await openDashboard(page, theme, WIDE);
    await expect(entitiesPanel(page).getByRole("tab", { name: "Entities" })).toHaveAttribute(
      "aria-selected",
      "true",
    );
    const results = await new AxeBuilder({ page }).exclude(".maplibregl-canvas").analyze();
    expect(
      results.violations.map((v) => `${v.id}: ${v.nodes.map((n) => n.target).join(", ")}`),
    ).toEqual([]);
  });
}

test("at 1280x800 the left panel starts collapsed and the toggle opens it", async ({ page }) => {
  await openDashboard(page, "ops", NARROW);
  await expect(panelToggle(page)).toHaveAttribute("aria-expanded", "false");
  await expect(entitiesPanel(page).getByRole("tab", { name: "Log" })).toBeHidden();
  await panelToggle(page).click();
  await expect(panelToggle(page)).toHaveAttribute("aria-expanded", "true");
  await expect(entitiesPanel(page).getByRole("tab", { name: "Log" })).toBeVisible();
});

test("at 1600x900 the left panel starts open and the toggle collapses it", async ({ page }) => {
  await openDashboard(page, "ops", WIDE);
  await expect(panelToggle(page)).toHaveAttribute("aria-expanded", "true");
  await panelToggle(page).click();
  await expect(panelToggle(page)).toHaveAttribute("aria-expanded", "false");
});

test("the layout keeps one banner, one main, a navigation and the Entities landmark", async ({
  page,
}) => {
  await openDashboard(page, "ops", WIDE);
  await expect(page.getByRole("banner")).toHaveCount(1);
  await expect(page.getByRole("main")).toHaveCount(1);
  await expect(page.getByRole("banner").getByRole("navigation", { name: "Pages" })).toBeVisible();
  await expect(page.getByRole("complementary")).toHaveCount(1); // no selection: no Inspector
});

test("at 1280x800 no panel overlaps the command bar and none leaves the viewport", async ({
  page,
}) => {
  await openDashboard(page, "ops", NARROW);
  const bar = await page.getByRole("banner").boundingBox();
  const panel = await entitiesPanel(page).boundingBox();
  expect(bar).not.toBeNull();
  expect(panel).not.toBeNull();
  if (!bar || !panel) return;
  expect(panel.y).toBeGreaterThanOrEqual(bar.y + bar.height);
  expect(panel.x + panel.width).toBeLessThanOrEqual(NARROW.width);
  expect(panel.y + panel.height).toBeLessThanOrEqual(NARROW.height);
});

test("the left panel is glass and holds no glass inside (never glass on glass)", async ({
  page,
}) => {
  await openDashboard(page, "ops", WIDE);
  const panel = entitiesPanel(page).locator(".vt-panel").first();
  await expect(panel).toHaveCSS("backdrop-filter", /blur/);
  const nested = await panel.evaluate(
    (el) =>
      [...el.querySelectorAll("*")].filter((c) => getComputedStyle(c).backdropFilter !== "none")
        .length,
  );
  expect(nested).toBe(0);
});

// ---- WI-14 review round: the bar in every live run state (ASM-986) ------------------------------------------------
// The `ui` project has no engine, so a fake stream is installed with `page.routeWebSocket`: a hello, then one frame
// with the given run state. The REST calls the page makes on its own are none while no command is sent.
type RunState = "idle" | "ready" | "running" | "paused";
type Live = {
  state: RunState;
  clock: Record<string, unknown>;
  /** The readouts: `typical` or the widest values the bar can show (T+99:59:59, tick 9,999,999, 10,000 entities). */
  values?: "typical" | "worst";
};
const HELLO = {
  type: "hello",
  protocol: "umbra.stream.v1",
  api_version: "1.0.0",
  encoding: "json",
  settings: {
    default_rate_hz: 30,
    max_rate_hz: 60,
    max_entity_ids: 10000,
    max_events_per_frame: 4096,
    max_message_bytes: 16_000_000,
    queue_frames: 4,
    send_timeout_s: 10,
  },
};
const entity = (id: number, name: string, force: string) => ({
  id,
  name,
  lat_deg: 52 + (id % 100) * 0.01,
  lon_deg: 5 + (id % 100) * 0.01,
  alt_m: 0,
  heading_deg: 0,
  speed_mps: 1,
  ownership: "owned",
  force,
});
const frameOf = ({ state, clock, values = "typical" }: Live, seq = 0) => {
  const worst = values === "worst";
  const count = state === "idle" ? 0 : worst ? 10_000 : 2;
  const tick = worst ? 9_999_999 : 42;
  const time = worst ? 359_999 : 1.4; // T+99:59:59
  return {
    type: "frame",
    kind: "snapshot",
    cause: "tick",
    session: 1,
    seq,
    tick,
    time_s: time,
    dropped: 0,
    entities: Array.from({ length: count }, (_, i) =>
      entity(i + 1, `Unit ${i + 1}`, i % 2 === 0 ? "blue" : "red"),
    ),
    events: [],
    events_truncated: false,
    run: { state, session: 1, clock, step_pending: false, tick, time_s: time },
  };
};

async function openLive(
  page: Page,
  theme: Theme,
  viewport: { width: number; height: number },
  live: Live,
): Promise<(next: Live) => void> {
  let socket: { send(message: string): void } | undefined;
  let seq = 0;
  await page.routeWebSocket(/\/api\/v1\/stream/, (ws) => {
    socket = ws;
    ws.send(JSON.stringify(HELLO));
    ws.send(JSON.stringify(frameOf(live, seq)));
  });
  await page.setViewportSize(viewport);
  await page.goto("/");
  await expect(page.getByText(/^(Idle|Ready|Running|Paused)$/).first()).toBeVisible();
  if (theme === "day") await page.getByRole("switch", { name: "Day theme" }).click();
  await expect(page.locator("html")).toHaveAttribute(
    "data-theme",
    theme === "day" ? "light" : "dark",
  );
  await page.mouse.move(0, 0);
  await page.evaluate(async () => {
    await document.fonts.ready;
  });
  await page.evaluate(() => new Promise<void>((done) => requestAnimationFrame(() => done())));
  // the bar settles: measurement, step, measurement (a few frames at most)
  await page.evaluate(
    () =>
      new Promise<void>((done) =>
        requestAnimationFrame(() =>
          requestAnimationFrame(() => requestAnimationFrame(() => done())),
        ),
      ),
  );
  return (next) => socket?.send(JSON.stringify(frameOf(next, ++seq)));
}

const STATES: [string, Live["state"], Record<string, unknown>][] = [
  ["idle", "idle", { mode: "realtime" }],
  ["ready", "ready", { mode: "realtime" }],
  ["running", "running", { mode: "realtime" }],
  ["running with a stepped clock", "running", { mode: "stepped" }],
  ["paused", "paused", { mode: "realtime" }],
];
const WIDTHS = [1280, 1366, 1440, 1536, 1600];
const VALUES = ["typical", "worst"] as const;

// The command bar holds every button in one row at every common width, state and readout size (ASM-988). The check
// is geometric and per element: a wrapping row keeps `scrollWidth == clientWidth`, so overflow alone proves nothing.
for (const width of WIDTHS) {
  for (const values of VALUES) {
    for (const [stateName, state, clock] of STATES) {
      test(`the command bar holds every button in one row: ${stateName}, ${values} values, ${width} px`, async ({
        page,
      }) => {
        await openLive(page, "ops", { width, height: 800 }, { state, clock, values });
        const bar = page.getByRole("banner");
        const barBox = await bar.boundingBox();
        expect(barBox).not.toBeNull();
        if (!barBox) return;
        expect(barBox.height).toBeLessThanOrEqual(64); // one row (the ui-kit bar is 48 px high)
        const overflow = await bar.evaluate((el) =>
          [el, ...el.querySelectorAll(".vt-cmdbar-actions")].map(
            (e) => e.scrollWidth - e.clientWidth,
          ),
        );
        for (const o of overflow) expect(o).toBeLessThanOrEqual(0);
        const items = bar.locator(
          "button, [role=switch], a, dl, :scope > *, .vt-cmdbar-actions > *",
        );
        const count = await items.count();
        expect(count).toBeGreaterThan(6);
        let boxes = 0;
        for (let i = 0; i < count; i++) {
          const box = await items.nth(i).boundingBox(); // null for a hidden item (the closed clock panel)
          if (!box) continue;
          boxes += 1;
          expect(box.x).toBeGreaterThanOrEqual(barBox.x - 1);
          expect(box.y).toBeGreaterThanOrEqual(barBox.y - 1);
          expect(box.x + box.width).toBeLessThanOrEqual(barBox.x + barBox.width + 1);
          expect(box.y + box.height).toBeLessThanOrEqual(barBox.y + barBox.height + 1);
        }
        expect(boxes).toBeGreaterThan(6);
        // every lifecycle button is still there and named, whichever step the bar took
        const group = page.getByRole("group", { name: "Run controls" });
        await expect(group.getByRole("button")).toHaveCount(6);
        for (const name of ["Load", "Start", "Pause", "Resume", "Stop", "Unload"]) {
          await expect(group.getByRole("button", { name, exact: true })).toBeVisible();
        }
      });
    }
  }
}

for (const theme of THEMES) {
  test(`dashboard while running at 1280x800 (${theme})`, async ({ page }) => {
    await openLive(page, theme, NARROW, { state: "running", clock: { mode: "realtime" } });
    await expect(page.locator(".maplibregl-canvas")).toHaveCount(1);
    await page.addStyleTag({ content: ".maplibregl-canvas { visibility: hidden !important; }" });
    await expect(page).toHaveScreenshot(`dashboard-running-${theme}.png`, SHOT);
  });

  test(`dashboard with the widest readouts at 1366x768 (${theme})`, async ({ page }) => {
    await openLive(
      page,
      theme,
      { width: 1366, height: 768 },
      { state: "running", clock: { mode: "realtime" }, values: "worst" },
    );
    await expect(page.locator(".maplibregl-canvas")).toHaveCount(1);
    await page.addStyleTag({ content: ".maplibregl-canvas { visibility: hidden !important; }" });
    await expect(page).toHaveScreenshot(`dashboard-worst-${theme}.png`, SHOT);
  });
}

// The Clock panel hangs from the bar's right edge: with an alert showing (no engine) it never covers it.
for (const width of WIDTHS) {
  test(`the open Clock panel does not cover the alert at ${width} px`, async ({ page }) => {
    await page.setViewportSize({ width, height: 800 });
    await page.goto("/");
    const alert = page.getByRole("alert", { name: "Engine not reachable" });
    await expect(alert).toBeVisible();
    await page.getByRole("button", { name: "Clock" }).click();
    const panel = page.getByRole("region", { name: "Clock" });
    await expect(panel).toBeVisible();
    const [a, p] = [await alert.boundingBox(), await panel.boundingBox()];
    expect(a).not.toBeNull();
    expect(p).not.toBeNull();
    if (!a || !p) return;
    const overlap =
      a.x < p.x + p.width && p.x < a.x + a.width && a.y < p.y + p.height && p.y < a.y + a.height;
    expect(overlap).toBe(false);
    expect(p.x + p.width).toBeLessThanOrEqual(width);
  });
}

test("a failed step shows its Alert in the alert column, wrapped and inside the viewport", async ({
  page,
}) => {
  const detail = `${"the engine refused this step because ".repeat(6)}and says so at length`;
  await page.route("**/api/v1/run/step", (route) =>
    route.fulfill({
      status: 409,
      contentType: "application/problem+json",
      body: JSON.stringify({
        type: "about:blank#step_cancelled",
        code: "step_cancelled",
        title: "Step cancelled",
        status: 409,
        detail,
      }),
    }),
  );
  await openLive(page, "ops", NARROW, { state: "running", clock: { mode: "stepped" } });
  await page.getByRole("button", { name: "Clock" }).click();
  await page.getByRole("button", { name: "Step 1 tick" }).click();
  const alert = page.getByRole("alert").filter({ hasText: "Step cancelled" });
  await expect(alert).toBeVisible();
  const box = await alert.boundingBox();
  expect(box).not.toBeNull();
  if (!box) return;
  expect(box.x).toBeGreaterThanOrEqual(0);
  expect(box.x + box.width).toBeLessThanOrEqual(NARROW.width);
  expect(box.height).toBeGreaterThan(60); // the long detail wrapped onto several lines
  const clipped = await alert.evaluate((el) => el.scrollWidth > el.clientWidth + 1);
  expect(clipped).toBe(false);
});

test("a running stepped clock keeps its Step group in the Clock panel, inside the viewport", async ({
  page,
}) => {
  await openLive(page, "ops", NARROW, { state: "running", clock: { mode: "stepped" } });
  await page.getByRole("button", { name: "Clock" }).click();
  const step = page.getByRole("group", { name: "Step" });
  await expect(step).toBeVisible();
  const box = await step.boundingBox();
  expect(box).not.toBeNull();
  if (!box) return;
  expect(box.x).toBeGreaterThanOrEqual(0);
  expect(box.x + box.width).toBeLessThanOrEqual(NARROW.width);
  expect(box.y + box.height).toBeLessThanOrEqual(NARROW.height);
});

test("Escape closes the Scenario panel and focus returns to its button", async ({ page }) => {
  await openLive(page, "ops", NARROW, { state: "running", clock: { mode: "realtime" } });
  const button = page.getByRole("button", { name: "Scenario" });
  await button.click();
  await expect(page.getByRole("region", { name: "Scenario" })).toBeVisible();
  await page.keyboard.press("Escape");
  await expect(page.getByRole("region", { name: "Scenario" })).toHaveCount(0);
  await expect(button).toBeFocused();
});

// WI-14 round 3 (ASM-990): the fit restarts when the fonts load and when the content shrinks, so a fresh load with the
// widest readouts at 1600 px settles at level 1 at most (labelled lifecycle buttons) and returns to the full bar
// (title shown) when the run goes idle and the counters reset.
test("at 1600 px a fresh load with the widest readouts settles at level 1 or less, and idle returns to level 0", async ({
  page,
}) => {
  const send = await openLive(page, "ops", WIDE, {
    state: "running",
    clock: { mode: "realtime" },
    values: "worst",
  });
  const group = page.getByRole("group", { name: "Run controls" });
  await expect(group.getByRole("button", { name: "Start", exact: true })).toHaveText("Start");
  send({ state: "idle", clock: { mode: "realtime" }, values: "typical" });
  await expect(page.getByRole("banner").locator("b", { hasText: "Live map" })).toBeVisible();
});
